  // esearch via POST (PATCH_414_v1) : term dans le corps -> plus de HTTP 414 sur equation longue
  const esearchBase = 'https://eutils.ncbi.nlm.nih.gov/entrez/eutils/esearch.fcgi';
  // BORNES DE DATES (2026-08-03). Elles etaient extraites puis jamais utilisees : le compte
  // etait identique avec et sans, donc le filtre etait silencieusement ignore. On passe par
  // les parametres d'intervalle de l'interface de programmation, ce qui laisse l'equation
  // validee par l'utilisateur intacte et garde le filtre visible dans la trace.
  const _bornesDate = (function(){
    const norm = function(v, finDAnnee){
      const s = String(v || '').trim();
      if (!s) return '';
      const m = s.match(/^(\d{4})(?:-(\d{2}))?(?:-(\d{2}))?$/);
      if (!m) return '';
      const a = m[1];
      const mo = m[2] || (finDAnnee ? '12' : '01');
      const j = m[3] || (finDAnnee ? '31' : '01');
      return a + '/' + mo + '/' + j;
    };
    const d1 = norm(input.date_start, false);
    const d2 = norm(input.date_end, true);
    if (!d1 && !d2) return '';
    // Une seule borne est licite : l'autre prend une valeur extreme.
    return '&datetype=pdat&mindate=' + encodeURIComponent(d1 || '1800/01/01')
         + '&maxdate=' + encodeURIComponent(d2 || '3000/12/31');
  })();
  const esearchBody = 'db=pubmed&retmax=0&retmode=json&term=' + encodeURIComponent(rawQuery) + _bornesDate;
  let resp = await this.helpers.httpRequest({
    method: 'POST',
    url: PROXY + '?url=' + encodeURIComponent(esearchBase),
    body: esearchBody,
    headers: { 'Content-Type': 'application/x-www-form-urlencoded' },
    timeout: 30000
  });
  if (typeof resp === 'string') { try { resp = JSON.parse(resp); } catch (e) { resp = {}; } }
