// Apply global cap (apres merge de toutes les sources)
// SEARCH_DEDUP_MERGE_v1 - dedup par DOI (sinon titre+annee) + fusion des champs (recupere l'abstract depuis la source qui l'a)
function __normDoi(d){
  // MEME REGLE QUE `text_norm.norm_doi`, PLUS UNE DIFFERENCE ASSUMEE : cette
  // valeur-ci sert a CONSTRUIRE UNE ADRESSE D'INTERROGATION, pas une clef de
  // deduplication. Un espace INTERNE y casserait la requete, et il est donc
  // resserre. Mesure sur les 376 042 identifiants du poste : 6 valeurs portent
  // un espace interne, pour 2 identifiants distincts, et AUCUN doublon n'est
  // manque de ce fait (la forme sans espace n'existe nulle part dans le
  // corpus). Le retrait du prefixe textuel, lui, manquait : `doi:10.1/x`
  // produisait l'adresse `DOI:doi:10.1/x`.
  return String(d || '').trim().toLowerCase()
    .replace(/^doi\s*:\s*/, '')
    .replace(/^https?:\/\/(dx\.)?doi\.org\//, '')
    .replace(/^doi\s*:\s*/, '')
    .replace(/\s+/g, '')
    .trim();
}
function __normTitle(t){ return String(t||'').toLowerCase().replace(/[^a-z0-9]+/g,' ').replace(/\s+/g,' ').trim(); }
// === REGLE UNIQUE DE SURVIE D'UN DOUBLON (A7, 2026-08-04) ===
// COPIE MOT POUR MOT de src/notice_merge.py. Les nœuds n8n n'important rien, c'est la seule
// forme de partage possible ; un test croise execute les deux implantations sur le meme jeu et
