// La question « quelle notice garde-t-on » recevait QUATRE reponses differentes selon le
// chemin. MESURE : deux notices de meme DOI, l'une SANS resume et l'autre avec 106 caracteres,
// rendaient la notice SANS resume, qui tombait ensuite sous le seuil de 50 caracteres du tri
// et sortait « Maybe » sans jamais avoir ete jugee.
// On fusionne, on ne choisit pas : le representant est la notice la plus complete, et il
// recupere de chaque doublon tout champ qui lui manque.
function __ulVide(v) {
  if (v === null || v === undefined) return true;
  if (typeof v === 'string') return v.trim() === '';
  if (Array.isArray(v)) return v.length === 0;
  if (typeof v === 'object') return Object.keys(v).length === 0;
