        }
      } catch (e) { console.log('PubMed enrich error: ' + (e && e.message ? e.message : e)); }
    }
    console.log('Abstract enrich cascade (S2->OpenAlex->EuropePMC->PubMed): ' + __absEnriched + ' abstracts recuperes');
