// BASE_TOGGLE_v1 // GREYLIT_SOURCES_v1 : ClinicalTrials + Europe PMC + ISRCTN
const input = $('Extract Params').first().json;
const gate = ($input.all()[0] && $input.all()[0].json) || {};
const clean = function(s){ return (s||'').toString().replace(/[*?~]/g,' ').replace(/\s+/g,' ').trim(); };
const out = [];

// --- ClinicalTrials.gov ---
if (gate.enable_clinicaltrials === true) {
  const q = clean(input.clinicaltrials_query || input.doaj_query || input.openalex_query || input.pubmed_query || input.question);
  if (!q) { out.push({ json: { _source: 'clinicaltrials', count: 0 } }); }
  else {
    try {
      const __y1 = parseInt(input.date_start) || 0, __y2 = parseInt(input.date_end) || 0;
    const __qd = (__y1 || __y2) ? (q + ' AND AREA[StartDate]RANGE[' + (__y1 ? (__y1 + '-01-01') : 'MIN') + ',' + (__y2 ? (__y2 + '-12-31') : 'MAX') + ']') : q;
    const url = 'https://clinicaltrials.gov/api/v2/studies?format=json&pageSize=1&countTotal=true&query.term=' + encodeURIComponent(__qd);
      const resp = await this.helpers.httpRequest({ method: 'GET', url: url, headers: { 'User-Agent': 'UltraLab-SystematicReview/1.0', 'Accept': 'application/json' }, timeout: 30000, json: true }); // CT_DIRECT_v1
      out.push({ json: { _source: 'clinicaltrials', count: (resp && resp.totalCount) || 0 } });
    } catch (e) { out.push({ json: { _source: 'clinicaltrials', count: 0, error: e.message } }); }
  }
} else { out.push({ json: { _source: 'clinicaltrials', count: 0, _disabled_by_user: true } }); }

// --- Europe PMC (inclut les preprints via SRC:PPR dans la query si demande) ---
if (gate.enable_europepmc === true) {
  const q = clean(input.europepmc_query || input.openalex_query || input.pubmed_query || input.question);
  if (!q) { out.push({ json: { _source: 'europepmc', count: 0 } }); }
  else {
    try {
      const __y1 = parseInt(input.date_start) || 0, __y2 = parseInt(input.date_end) || 0;
    const __qd = (__y1 || __y2) ? (q + ' AND (PUB_YEAR:[' + (__y1 || 0) + ' TO ' + (__y2 || 3000) + '])') : q;
    const url = 'https://www.ebi.ac.uk/europepmc/webservices/rest/search?format=json&pageSize=1&query=' + encodeURIComponent(__qd);
      const resp = await this.helpers.httpRequest({ method: 'GET', url: url, headers: { 'User-Agent': 'UltraLab-SystematicReview/1.0', 'Accept': 'application/json' }, timeout: 30000, json: true });
      out.push({ json: { _source: 'europepmc', count: (resp && resp.hitCount) || 0 } });
    } catch (e) { out.push({ json: { _source: 'europepmc', count: 0, error: e.message } }); }
  }
} else { out.push({ json: { _source: 'europepmc', count: 0, _disabled_by_user: true } }); }

// --- ISRCTN (registre d'essais, XML format OMS ; totalCount lu par decoupage de chaine) ---
if (gate.enable_isrctn === true) {
  const q = clean(input.isrctn_query || input.question || input.openalex_query || input.pubmed_query);
  if (!q) { out.push({ json: { _source: 'isrctn', count: 0 } }); }
  else {
    try {
      const url = 'https://www.isrctn.com/api/query/format/default?limit=1&q=' + encodeURIComponent(q);
      const xml = await this.helpers.httpRequest({ method: 'GET', url: url, headers: { 'User-Agent': 'UltraLab-SystematicReview/1.0' }, timeout: 30000 });
      const s = String(xml);
      const k = s.indexOf('totalCount="');
      let n = 0;
      if (k >= 0) { const e2 = s.indexOf('"', k + 12); n = parseInt(s.slice(k + 12, e2)) || 0; }
      out.push({ json: { _source: 'isrctn', count: n } });
    } catch (e) { out.push({ json: { _source: 'isrctn', count: 0, error: e.message } }); }
  }
} else { out.push({ json: { _source: 'isrctn', count: 0, _disabled_by_user: true } }); }

return out;
